import type {Bilingual} from './exam-data';
const b=(en:string,cs:string):Bilingual=>({en,cs});
const u=(title:Bilingual,...paragraphs:Bilingual[])=>({title,paragraphs});
const r=(term:Bilingual,mechanism:Bilingual,meaning:Bilingual)=>({term,mechanism,meaning});
export type TheoryChapter={lead:Bilingual;units:{title:Bilingual;paragraphs:Bilingual[]}[];rows:{term:Bilingual;mechanism:Bilingual;meaning:Bilingual}[];example:Bilingual;reading:{book:string;page:number}};
export const theoryChapters:Record<string,TheoryChapter>={
 anatomy:{lead:b('Understand a structure by connecting its material, attachments, movement and stabilizing role. Anatomy becomes useful when you can explain how force travels through a limb and which structures constrain it.','Struktuře porozumíte propojením jejího složení, úponů, pohybu a stabilizační úlohy. Anatomie je použitelná, když vysvětlíte průchod síly končetinou a struktury, které pohyb omezují.'),units:[
 u(b('1. Organization: tissues, planes and joints','1. Uspořádání: tkáně, roviny a klouby'),b('The axial skeleton includes skull, vertebral column, ribs and sternum; the appendicular skeleton includes limb girdles and limbs. Compact bone forms a strong cortex, while trabecular bone organizes internal support. Periosteum is a vascular, innervated covering with a role in repair. Articular cartilage differs: it has no direct blood supply and is maintained partly by exchange with synovial fluid. This helps explain why bone and cartilage injuries behave differently.','Osovou kostru tvoří lebka, páteř, žebra a sternum, kostru končetin pletence a končetiny. Kompaktní kost vytváří pevnou kortikalis, trámčitá kost vnitřní oporu. Okostice je prokrvený a inervovaný obal s úlohou v hojení. Kloubní chrupavka naproti tomu nemá přímé cévní zásobení a je vyživována také výměnou se synoviální tekutinou. To pomáhá vysvětlit rozdílné chování jejich poranění.'),b('A sagittal plane separates left and right, a dorsal plane separates dorsal and ventral portions, and a transverse plane crosses the long axis of the body or segment. Flexion and extension change the angle at a joint; abduction and adduction move relative to the median plane; rotation occurs around a segment’s long axis. Name the joint and reference position, because a word such as “forward” depends on the observer.','Sagitální rovina odděluje levou a pravou část, dorzální hřbetní a břišní část a transverzální protíná dlouhou osu těla či segmentu. Flexe a extenze mění kloubní úhel, abdukce a addukce vztah ke střední rovině a rotace probíhá kolem dlouhé osy segmentu. Uveďte kloub a výchozí polohu, protože slovo „dopředu“ závisí na pozorovateli.')),
 u(b('2. Follow force through both limbs','2. Sledujte sílu oběma končetinami'),b('The canine forelimb connects to the trunk through a muscular sling rather than a conventional bony articulation. Serratus ventralis contributes support between scapula and trunk. The shoulder transfers load toward the humerus, elbow and antebrachium; triceps acts through the olecranon to extend the elbow. At the distal limb, tendons and ligamentous support help resist joint collapse under weight. Stabilization is shared by active muscle control and passive tissues.','Hrudní končetina psa je k trupu připojena svalovým závěsem, nikoli běžným kostěným kloubem. Serratus ventralis přispívá k opoře mezi lopatkou a trupem. Rameno přenáší zátěž na humerus, loket a předloktí; triceps přes olekranon extenduje loket. Distálně šlachy a vazivová opora pomáhají odolávat propadání kloubů pod vahou. Stabilizaci sdílí aktivní svalové řízení a pasivní tkáně.'),b('The pelvic limb connects through the hip and sacroiliac region. Hip extensors contribute to propulsion; quadriceps transmits force through the patella and patellar ligament to the tibial tuberosity. The stifle must permit flexion while controlling translation and rotation. Menisci improve contact and distribute load between femur and tibia. At the hock, the common calcaneal tendon combines contributions from several muscles; its role cannot be reduced to a single bone label.','Pánevní končetina se připojuje přes kyčel a sakroiliakální oblast. Extenzory kyčle přispívají k odrazu, kvadriceps přenáší sílu přes čéšku a čéškový vaz na tuberositas tibiae. Koleno umožňuje flexi a současně řídí posun a rotaci. Menisky zlepšují kontakt a rozkládají zatížení mezi femurem a tibií. Společná patní šlacha u hlezna zahrnuje příspěvky několika svalů; její úlohu nevystihuje název jedné kosti.')),
 u(b('3. Spine, muscles and three-dimensional relationships','3. Páteř, svaly a prostorové vztahy'),b('Vertebral bodies carry load, arches surround the vertebral canal and processes provide articulations and attachments. Facet orientation helps determine regional mobility. Epaxial muscles contribute extension and stabilization; hypaxial and abdominal muscles influence flexion and trunk control. A muscle’s action depends on its line of pull relative to the joint axis, not simply on being located “above” or “below” a bone.','Těla obratlů přenášejí zátěž, oblouky ohraničují páteřní kanál a výběžky poskytují kloubní plochy a úpony. Orientace kloubních plošek spoluurčuje pohyblivost úseku. Epaxiální svaly přispívají k extenzi a stabilizaci, hypaxiální a břišní k flexi a řízení trupu. Funkce svalu závisí na směru tahu vůči ose kloubu, nikoli pouze na poloze „nad“ či „pod“ kostí.'),b('Learn attachments together with innervation: triceps is supplied by the radial nerve, quadriceps by the femoral nerve, and gastrocnemius by the tibial nerve. This links anatomy to possible loss of function after nerve injury. On a living animal, indicate only landmarks you can identify reliably; deep joint structures need a specimen or imaging. Always distinguish dog-specific anatomy from feline differences.','Úpony se učte spolu s inervací: triceps zásobuje n. radialis, kvadriceps n. femoralis a gastrocnemius n. tibialis. Tím spojíte anatomii s možnou ztrátou funkce po poranění nervu. Na živém zvířeti ukazujte jen spolehlivě určitelné body; hluboké kloubní struktury vyžadují preparát či zobrazování. Odlišujte psí anatomii od kočičích zvláštností.'))
 ],rows:[r(b('Tendon','Šlacha'),b('Transmits muscle tension','Přenáší svalové napětí'),b('Connect action to insertion and crossed joints.','Propojte funkci s úponem a překlenujícími klouby.')),r(b('Ligament','Vaz'),b('Constrains relative motion','Omezuje vzájemný pohyb'),b('Explain the direction of instability after injury.','Vysvětlete směr nestability po poškození.')),r(b('Meniscus','Meniskus'),b('Fibrocartilage modifies joint contact','Vazivová chrupavka upravuje kloubní kontakt'),b('Distinguish load distribution from ligament restraint.','Odlište rozložení zatížení od omezení vazem.'))],example:b('Example: to explain elbow extension, identify humerus, ulna, elbow axis, triceps insertion on the olecranon and radial innervation. Then explain that extending the elbow against ground reaction involves both muscle force and joint stability. Pointing at the olecranon alone demonstrates identification, not understanding of the movement.','Příklad: při vysvětlení extenze lokte určete humerus, ulnu, osu lokte, úpon tricepsu na olekranon a radiální inervaci. Potom vysvětlete, že extenze proti reakci podložky zahrnuje svalovou sílu i stabilitu kloubu. Samotné ukázání olekranonu prokazuje poznání struktury, nikoli porozumění pohybu.'),reading:{book:'canine-rehabilitation',page:52}},
 physiology:{lead:b('Movement emerges from neural control, muscle force, energy supply and mechanics. A change in any one can alter the same visible task, so explain the mechanism before choosing an exercise.','Pohyb vzniká spoluprací nervového řízení, svalové síly, energetického zásobení a mechaniky. Změna kterékoliv složky může ovlivnit stejný viditelný úkol, proto před výběrem cvičení vysvětlete mechanismus.'),units:[
 u(b('1. From a signal to a contraction','1. Od signálu ke kontrakci'),b('A neuron maintains an electrical gradient across its membrane. When threshold is reached, voltage-gated channels generate an action potential. Myelin permits rapid conduction between nodes. At the neuromuscular junction, acetylcholine triggers a muscle-fibre action potential; calcium released within the fibre allows actin–myosin interaction. ATP is required for cross-bridge cycling and for processes that restore the resting state. Contraction therefore requires intact neural input, cellular machinery and energy.','Neuron udržuje elektrický gradient membrány. Po dosažení prahu napěťově řízené kanály vytvářejí akční potenciál. Myelin umožňuje rychlé vedení mezi zářezy. Na nervosvalové ploténce acetylcholin vyvolá potenciál svalového vlákna; uvolněný vápník umožní interakci aktinu a myozinu. ATP je nutné pro cyklus příčných můstků i obnovu klidového stavu. Kontrakce tedy vyžaduje nervový vstup, buněčný aparát a energii.'),b('Recruiting additional motor units and changing their firing rate modulates force. This differs from improving coordination between muscles. A patient may have enough force for a simple action yet poorly time limb placement. Sensory feedback from muscle, tendon, joint and skin helps the nervous system adapt movement. Proprioception informs body position, while vestibular and visual information contribute orientation and balance.','Sílu mění nábor dalších motorických jednotek a frekvence jejich výbojů. To se liší od zlepšení koordinace mezi svaly. Pacient může mít sílu pro jednoduchý pohyb, ale špatně načasovat položení končetiny. Zpětná vazba ze svalu, šlachy, kloubu a kůže pomáhá přizpůsobovat pohyb. Propriocepce informuje o poloze těla, vestibulární a zrakové informace přispívají k orientaci a rovnováze.')),
 u(b('2. Energy systems and adaptation','2. Energetické systémy a adaptace'),b('Stored ATP and phosphocreatine support immediate demand; glycolysis and oxidative metabolism contribute as activity continues. These systems overlap rather than switching on one at a time. Higher intensity changes the relative contribution and fatigue pattern. Training can alter cardiovascular delivery, metabolic capacity and neuromuscular efficiency, but adaptation is specific to the task and requires recovery. A trained sprinter is not automatically prepared for prolonged activity.','Zásoby ATP a kreatinfosfátu podporují okamžitou potřebu, při pokračování se podílejí glykolýza a oxidativní metabolismus. Systémy se překrývají, nezapínají se jednotlivě. Vyšší intenzita mění jejich podíl a podobu únavy. Trénink může změnit oběhové zásobení, metabolickou kapacitu a nervosvalovou účinnost, adaptace je však specifická a potřebuje zotavení. Trénovaný sprinter není automaticky připraven na dlouhou aktivitu.'),b('Disuse and illness reduce capacity, while pain may suppress normal recruitment and loading. Progression must account for the slowest relevant system, including healing connective tissue. Compare ordinary activity with sporting demands such as acceleration, braking and turning. For an exam answer, state which capacity you intend to improve and which observations would show intolerance rather than normal training effort.','Nepoužívání a nemoc snižují kapacitu, bolest může tlumit běžnou aktivaci a zatěžování. Postup musí zohlednit nejpomalejší podstatnou složku včetně hojícího se pojiva. Porovnejte běžnou aktivitu se sportovními nároky, například zrychlováním, brzděním a zatáčením. V odpovědi uveďte cílovou schopnost i nálezy nesnášenlivosti zátěže oproti běžnému úsilí.')),
 u(b('3. Mechanics of a whole task','3. Mechanika celého úkolu'),b('Force changes motion; torque is force multiplied by the perpendicular moment arm. Work involves force through displacement, while power expresses how quickly work is done. During stance, the ground reaction acts on the paw and generates demands at successive joints. During swing, the limb must clear the ground and reach the next support position. Trunk and head motion can redistribute demand without restoring normal function of an injured limb.','Síla mění pohyb; moment síly je síla krát kolmé rameno. Práce zahrnuje působení síly po dráze, výkon rychlost vykonání práce. V opoře působí reakce podložky na tlapku a vytváří nároky v navazujících kloubech. Ve švihu musí končetina opustit podložku a dosáhnout další opory. Pohyb trupu a hlavy může přerozdělit nároky bez obnovy normální funkce poraněné končetiny.'),b('Muscle–tendon units store and transmit energy, while joint angles influence leverage and muscle length. Concentric, eccentric and isometric actions can occur within one everyday task. Observing only distance or repetitions misses these differences. Speed, surface and assistance should be recorded because each changes the mechanical problem and the interpretation of improvement.','Svalově-šlachové jednotky ukládají a přenášejí energii, kloubní úhly mění páku i délku svalu. V jednom běžném úkolu se mohou objevit koncentrické, excentrické a izometrické děje. Samotná vzdálenost či opakování rozdíly nezachytí. Rychlost, povrch a pomoc zapisujte, protože mění mechanickou úlohu i interpretaci zlepšení.'))
 ],rows:[r(b('Strength','Síla'),b('Capacity to produce force','Schopnost vytvářet sílu'),b('Do not infer it solely from task duration.','Neodvozujte ji jen z délky úkolu.')),r(b('Endurance','Vytrvalost'),b('Capacity to sustain or repeat activity','Schopnost udržet či opakovat aktivitu'),b('Assess fatigue and recovery as well as completion.','Hodnoťte únavu a zotavení i dokončení.')),r(b('Coordination','Koordinace'),b('Timing and organization of movement','Načasování a uspořádání pohybu'),b('More force does not necessarily improve placement.','Více síly nemusí zlepšit umístění končetiny.'))],example:b('Example: a dog rises once but becomes asymmetrical with repetition. Possible explanations include pain, fatigue and insufficient motor control. State what you would observe and measure to distinguish them, rather than prescribing more repetitions because the first attempt succeeded.','Příklad: pes jednou vstane, ale s opakováním je asymetrický. Možná vysvětlení zahrnují bolest, únavu a nedostatečné řízení. Uveďte pozorování a měření k jejich odlišení místo přidávání opakování jen proto, že první pokus vyšel.'),reading:{book:'canine-rehabilitation',page:166}},
 healing:{lead:b('Healing changes tissue capacity over time. The key question is not simply “How many days since injury?” but “What tissue is repairing, under what mechanical conditions, and how does it respond?”','Hojení mění kapacitu tkáně v čase. Podstatné není jen „Kolik dní od poranění?“, ale „Která tkáň se hojí, za jakých mechanických podmínek a jak reaguje?“'),units:[
 u(b('1. Overlapping phases and tissue differences','1. Překrývající se fáze a rozdíly tkání'),b('Hemostasis limits bleeding and forms an early scaffold. Inflammation removes damaged material and recruits repair signals. During proliferation, new vessels, fibroblasts and matrix contribute repair tissue; remodeling reorganizes collagen and modifies mechanical properties. These are overlapping processes, not rigid calendar compartments. Excessive movement, infection, poor perfusion and systemic disease can disrupt repair. Reduced swelling does not mean the repair has regained normal strength.','Hemostáza omezuje krvácení a vytváří časnou oporu. Zánět odstraňuje poškozený materiál a přivádí signály reparace. Při proliferaci vytvářejí nové cévy, fibroblasty a matrix reparační tkáň; remodelace reorganizuje kolagen a mechanické vlastnosti. Fáze se překrývají a nejsou pevnými kalendářními úseky. Nadměrný pohyb, infekce, špatné prokrvení a celkové nemoci mohou hojení narušit. Ústup otoku neznamená původní pevnost.'),b('Bone can regenerate through different pathways depending on stability and biology. Tendons and ligaments commonly repair with collagenous scar and prolonged remodeling. Muscle can regenerate from satellite-cell activity but may also develop fibrosis. Cartilage has limited repair capacity and may be replaced by tissue with different properties. Nerve recovery depends on the level and type of injury and whether axonal pathways and supporting structures remain usable.','Kost může regenerovat různými cestami podle stability a biologie. Šlachy a vazy se běžně opravují kolagenní jizvou s dlouhou remodelací. Sval může regenerovat aktivitou satelitních buněk, ale vzniká i fibróza. Chrupavka má omezenou reparaci a náhradní tkáň může mít jiné vlastnosti. Obnova nervu závisí na úrovni a typu poranění i zachování axonálních cest a podpůrných struktur.')),
 u(b('2. Pain and protection are related but not identical','2. Bolest a ochrana spolu souvisejí, nejsou totožné'),b('Nociception involves detection, transmission and processing of potentially damaging stimuli. Pain is the animal’s experience, inferred through behavior, function and examination. Inflammation can sensitize peripheral receptors; persistent input can alter central processing. Neuropathic pain arises from disease or injury affecting the somatosensory system. Therefore the intensity of observed pain need not match the visible size of a lesion, and absent vocalization does not establish comfort.','Nocicepce zahrnuje detekci, přenos a zpracování potenciálně škodlivých podnětů. Bolest je prožitek zvířete odhadovaný z chování, funkce a vyšetření. Zánět může senzitivizovat periferní receptory, trvalý vstup měnit centrální zpracování. Neuropatická bolest vzniká při nemoci či poranění somatosenzorického systému. Pozorovaná bolest proto nemusí odpovídat viditelné velikosti léze a nepřítomnost hlasových projevů neprokazuje pohodlí.'),b('Choose an assessment instrument suitable for the species and context, and repeat it consistently. Acute hospital pain and chronic home activity limitations may require different tools. Interpret the score alongside clinical findings and owner observations. Veterinary analgesia can enable appropriate movement, but symptom relief does not remove the mechanical restrictions of a healing repair.','Vyberte nástroj vhodný pro druh a situaci a opakujte jej jednotně. Akutní nemocniční bolest a chronické domácí omezení mohou vyžadovat jiné nástroje. Skóre vykládejte spolu s nálezem a pozorováním majitele. Veterinární analgezie může umožnit vhodný pohyb, ale úleva neodstraňuje mechanická omezení hojící se opravy.')),
 u(b('3. Loading, disuse and scars','3. Zatížení, nepoužívání a jizvy'),b('Loading provides mechanical signals, but the benefit depends on magnitude, direction, timing and tissue state. Too little activity can contribute to loss of muscle, joint mobility and tissue capacity; too much can disrupt repair. The rehabilitation task is to preserve permitted function while protecting the vulnerable structure. This balance requires the surgical or medical plan, not an assumed universal schedule.','Zátěž poskytuje mechanické signály, její přínos však závisí na velikosti, směru, načasování a tkáni. Příliš málo aktivity přispívá ke ztrátě svalů, pohyblivosti a kapacity; příliš mnoho může opravu narušit. Úkolem rehabilitace je zachovat povolenou funkci a chránit zranitelnou strukturu. Rovnováha vyžaduje chirurgický či léčebný plán, nikoli univerzální rozvrh.'),b('A scar should be assessed for wound condition, sensitivity, mobility and functional relevance. Surface closure is not equivalent to full maturation, and not every scar needs manual treatment. New discharge, opening, increasing redness, heat or pain calls for veterinary review. Manual scar work should not be used to override wound restrictions or to explain every distant symptom without supporting findings.','U jizvy posuzujte stav rány, citlivost, pohyblivost a funkční význam. Uzavření povrchu není úplné vyzrání a ne každá jizva potřebuje manuální ošetření. Nový výtok, rozevření, přibývající zarudnutí, teplo či bolest vyžadují veterinární kontrolu. Práce s jizvou nesmí obcházet omezení rány ani bez nálezů vysvětlovat všechny vzdálené příznaky.'))
 ],rows:[r(b('Pain relief','Úleva od bolesti'),b('A change in symptoms','Změna příznaků'),b('Does not prove restoration of tissue strength.','Neprokazuje obnovu pevnosti tkáně.')),r(b('Skin closure','Uzavření kůže'),b('Restored surface continuity','Obnovená spojitost povrchu'),b('Does not establish deep repair readiness.','Neprokazuje připravenost hluboké opravy.')),r(b('Remodeling','Remodelace'),b('Continuing tissue reorganization','Pokračující přestavba tkáně'),b('Loading must still follow response and restrictions.','Zátěž se stále řídí reakcí a omezeními.'))],example:b('Example: swelling improves after a tendon repair and the dog wants to run. Explain the difference between comfort and tensile capacity, verify the surgeon’s restrictions and choose only permitted activity. Record the response afterward; eagerness and a neat skin incision cannot establish tendon strength.','Příklad: po opravě šlachy ustoupí otok a pes chce běžet. Vysvětlete rozdíl pohodlí a tahové kapacity, ověřte omezení chirurga a vyberte pouze povolenou aktivitu. Zapište následnou reakci; chuť běžet a úhledná kožní rána pevnost šlachy neprokazují.'),reading:{book:'canine-rehabilitation',page:90}},
 assessment:{lead:b('Assessment turns observations into a defensible problem list. Use a repeatable sequence, identify urgent problems first and keep raw findings separate from their interpretation.','Vyšetření převádí pozorování na odůvodněný seznam problémů. Používejte opakovatelný postup, nejprve odhalte naléhavé potíže a oddělujte nález od výkladu.'),units:[
 u(b('1. History and general clinical context','1. Anamnéza a celkový klinický kontext'),b('Begin with the owner’s main concern, then establish onset, progression, side, circumstances, previous treatment and daily function. Ask what the animal could do before and what changed. Review medication, surgery, diagnostics, concurrent disease and veterinary restrictions. The home surface, stairs, owner’s physical ability and routine can determine whether a proposed plan is feasible. A history is a set of evidence and unanswered questions, not a diagnosis.','Začněte hlavní starostí majitele a zjistěte vznik, vývoj, stranu, okolnosti, léčbu a denní funkci. Ptejte se, co zvíře dříve zvládalo a co se změnilo. Projděte léky, operace, diagnostiku, souběžné nemoci a veterinární omezení. Povrch doma, schody, fyzické možnosti majitele a režim určují proveditelnost plánu. Anamnéza je soubor podkladů a otázek, nikoli diagnóza.'),b('Observe before handling: alertness, breathing effort, posture and interaction may change the priority of the visit. A focused limb examination is inappropriate if the animal is medically unstable. Clinical measurements require correct technique and context; stress can change pulse and respiration. Document what was actually examined and what was deferred, including the reason.','Pozorujte před manipulací: vědomí, dechové úsilí, postoj a interakce mohou změnit prioritu návštěvy. Zaměřené vyšetření končetiny není vhodné při celkové nestabilitě. Klinická měření potřebují správnou techniku a kontext; stres mění pulz i dech. Zapište skutečně provedené i odložené části a jejich důvod.')),
 u(b('2. Complementary examinations','2. Doplňující se druhy vyšetření'),b('Orthopedic assessment examines joints, bones and soft tissues for pain, swelling, mobility, muscle changes and stability. Neurological assessment examines control, coordination, reflexes and sensory pathways to help localize dysfunction. Rehabilitation assessment connects these findings to daily tasks and measurable limitations. These examinations overlap, but none replaces the others; pain and neurological weakness can coexist.','Ortopedické vyšetření hodnotí klouby, kosti a měkké tkáně: bolest, otok, pohyblivost, svaly a stabilitu. Neurologické posuzuje řízení, koordinaci, reflexy a čití pro lokalizaci poruchy. Rehabilitační spojuje nálezy s běžnými úkoly a měřitelným omezením. Oblasti se překrývají, ale nenahrazují; bolest a neurologická slabost mohou být současně.'),b('For range of motion and limb circumference, record position, landmarks, side, instrument and examiner. Repeating the same method reduces variation. A larger circumference might mean increased muscle, edema or measurement error; a larger angle may result from different stabilization. When possible combine an impairment measure with a functional task and an owner-reported outcome.','U rozsahu pohybu a obvodu končetiny zapisujte polohu, body, stranu, přístroj a hodnotitele. Stejná metoda omezuje variabilitu. Větší obvod může znamenat více svalů, otok či chybu; větší úhel jinou stabilizaci. Pokud lze, propojte měření poruchy s funkčním úkolem a hodnocením majitele.')),
 u(b('3. Gait analysis and reassessment','3. Analýza chůze a kontrola'),b('Separate stance from swing and describe speed, rhythm, stride length, support time, clearance and body compensation. Observe several directions under safe, comparable conditions. The side view helps with limb excursion; front and rear views help with placement and lateral deviation. Neither a head nod nor a single paw position identifies a specific lesion by itself. Video records a sample of behavior, not the whole clinical state.','Oddělte oporu a švih a popište rychlost, rytmus, délku kroku, dobu opory, zvedání tlapky a kompenzace. Bezpečně sledujte více směrů ve srovnatelných podmínkách. Bok pomáhá posoudit rozsah pohybu, přední a zadní pohled umístění a boční odchylky. Kývnutí hlavy ani poloha jedné tlapky samy neurčí lézi. Video zachycuje vzorek chování, nikoli celý stav.'),b('Reassessment asks whether change exceeds plausible measurement variation and matters to function. Keep speed, surface, assistance and recording method similar. If results disagree, investigate rather than selecting the most flattering number. A better questionnaire score with worsening skin or new neurological signs demands broader review, not automatic progression.','Kontrola zjišťuje, zda změna přesahuje pravděpodobnou variabilitu a má funkční význam. Zachovejte podobnou rychlost, povrch, pomoc a záznam. Při rozporech je objasněte místo volby nejpříznivějšího čísla. Lepší dotazníkové skóre při horší kůži či nových neurologických příznacích vyžaduje širší kontrolu, ne automatický postup.'))
 ],rows:[r(b('Observation','Pozorování'),b('What was seen or measured','Co bylo viděno či naměřeno'),b('“Right stance time appeared shorter.”','„Opora vpravo vypadala kratší.“')),r(b('Interpretation','Interpretace'),b('A possible explanation','Možné vysvětlení'),b('“Possible unloading; cause not established.”','„Možné odlehčení; příčina neurčena.“')),r(b('Decision','Rozhodnutí'),b('Next justified action','Další zdůvodněný krok'),b('Repeat comparably and examine the patient.','Zopakovat srovnatelně a vyšetřit pacienta.'))],example:b('Example: thigh circumference rises while walking deteriorates. Do not declare successful muscle gain. Check measurement landmarks, swelling, pain and recent activity, compare the full examination and communicate the discrepancy to the treating team. A single number should not overrule worsening function.','Příklad: obvod stehna roste, ale chůze se horší. Neoznačujte to za úspěšný nárůst svalů. Ověřte body měření, otok, bolest a nedávnou aktivitu, porovnejte celé vyšetření a sdělte rozpor týmu. Jediné číslo nemá přebít zhoršování funkce.'),reading:{book:'canine-rehabilitation',page:193}},
 orthopedics:{lead:b('Orthopedic rehabilitation protects vulnerable structures while restoring useful movement. The disease name is only the start: tissue state, procedure, fixation, pain and the animal’s actual function determine the plan.','Ortopedická rehabilitace chrání zranitelné struktury a obnovuje užitečný pohyb. Název nemoci je začátek: plán určuje tkáň, výkon, fixace, bolest a skutečná funkce zvířete.'),units:[
 u(b('1. Compare disorders by their mechanical problem','1. Porovnávejte nemoci podle mechanického problému'),b('Forelimb cases may involve elbow developmental disease and OA, shoulder tendon disorders, osteochondral disease, fractures or soft-tissue injury. Hindlimb cases commonly include cruciate disease, patellar luxation, hip dysplasia/OA and fractures. Each can cause lameness, but through different combinations of pain, instability, altered contact and restricted movement. Identify the affected structure and diagnostic evidence rather than building a plan from lameness alone.','Na hrudní končetině se objevují vývojové nemoci lokte a OA, šlachové poruchy ramene, osteochondrální nemoci, zlomeniny či měkkotkáňové úrazy. Na pánevní často onemocnění zkříženého vazu, luxace pately, dysplazie/OA kyčle a zlomeniny. Všechny mohou způsobit kulhání různou kombinací bolesti, nestability, kontaktu a omezení. Určete strukturu a diagnostický podklad místo plánu pouze podle kulhání.'),b('OA affects the whole joint, including cartilage, synovium, subchondral bone and surrounding tissues. Pain-related avoidance can reduce muscle capacity, which further limits function. Imaging helps describe structural disease, but radiographic severity and daily disability are not interchangeable. Management therefore combines medical pain care, appropriate activity, environmental adaptation and relevant nutritional planning.','OA postihuje celý kloub včetně chrupavky, synovie, subchondrální kosti a okolních tkání. Vyhýbání kvůli bolesti snižuje svalovou kapacitu a dále omezuje funkci. Zobrazování popisuje strukturu, ale rentgenová závažnost a denní omezení nejsou zaměnitelné. Péče proto propojuje léčbu bolesti, vhodnou aktivitu, prostředí a potřebnou výživu.')),
 u(b('2. Understand what surgery changes','2. Pochopte, co mění operace'),b('A repair may restore alignment, stabilize a fracture, alter joint mechanics or address damaged tissue. The rehabilitation constraints follow what was done. For example, a TPLO alters tibial geometry and includes a healing osteotomy; it is not a reconstruction of a normal cranial cruciate ligament. A soft-tissue repair creates different protection needs. Confirm the procedure and surgeon’s instructions rather than applying a generic “knee surgery” schedule.','Výkon může obnovit osu, stabilizovat zlomeninu, změnit mechaniku či řešit poškozenou tkáň. Rehabilitační omezení odpovídají skutečnému zásahu. Například TPLO mění geometrii tibie a zahrnuje hojící se osteotomii; není rekonstrukcí normálního kraniálního zkříženého vazu. Měkkotkáňová oprava potřebuje jinou ochranu. Ověřte výkon a pokyny místo obecného rozvrhu „po operaci kolene“.'),b('Protection does not necessarily mean absence of all movement, and improvement does not mean unrestricted loading. Identify which tasks are permitted, which forces threaten the repair and when reassessment is required. Pain, wound condition, limb use and imaging or surgical review may all affect progression. Avoid trying to demonstrate instability on a recently repaired joint during study practice.','Ochrana nemusí znamenat zákaz veškerého pohybu a zlepšení neznamená neomezené zatížení. Určete povolené úkoly, síly ohrožující opravu a termín kontroly. Postup ovlivňují bolest, rána, používání končetiny i zobrazovací či chirurgická kontrola. Při studiu nezkoušejte nestabilitu nedávno opraveného kloubu.')),
 u(b('3. Build and justify the plan','3. Sestavte a zdůvodněte plán'),b('Prioritize problems such as pain-limited support, reduced permitted motion, weakness and environmental barriers. Pair each with an outcome measure and a realistic goal. Select interventions with a reason: a comfortable permitted movement task for function, home footing for safety, or a clinically indicated modality for a defined target. Explain what is deliberately deferred and why.','Seřaďte problémy, například oporu omezenou bolestí, malý povolený rozsah, slabost a bariéry prostředí. Ke každému přiřaďte měřítko a realistický cíl. Metody vybírejte s důvodem: komfortní povolený úkol pro funkci, povrch pro bezpečnost nebo indikovaný prostředek pro konkrétní cíl. Vysvětlete i záměrně odložené zásahy.'),b('Progression needs acceptable movement quality, recovery and compliance with medical restrictions. A patient that completes a task by unloading the affected limb may be rehearsing compensation. New swelling, deteriorating weight bearing or wound changes require review. The owner needs a concise plan that states permitted activity and a response to deterioration, not merely a list of exercises.','Postup potřebuje přijatelnou kvalitu, zotavení a dodržení zdravotních omezení. Pacient dokončující úkol odlehčením postižené končetiny může nacvičovat kompenzaci. Nový otok, horší opora či změna rány vyžadují kontrolu. Majitel potřebuje stručný plán povolené aktivity a reakce na zhoršení, ne pouhý seznam cviků.'))
 ],rows:[r(b('Instability','Nestabilita'),b('Excess or poorly controlled motion','Nadměrný či špatně kontrolovaný pohyb'),b('Protect the structure; clarify stabilization.','Chraňte strukturu a objasněte stabilizaci.')),r(b('Restricted motion','Omezený pohyb'),b('May reflect pain, tissue or repair limits','Může odrážet bolest, tkáň či omezení opravy'),b('Do not assume every restriction should be stretched.','Nepředpokládejte potřebu protahovat každé omezení.')),r(b('Weakness','Slabost'),b('Reduced usable muscle capacity','Nižší využitelná svalová kapacita'),b('Choose permitted active loading after assessment.','Po posouzení vyberte povolené aktivní zatížení.'))],example:b('Example: a postoperative stifle patient has a comfortable wound but avoids the limb when rising. The problem list includes altered loading, not just muscle weakness. Verify restrictions, examine pain and movement, adapt the task and record a comparable baseline. Do not jump directly to an unstable balance cushion because “strengthening” is the goal.','Příklad: pacient po operaci kolene má klidnou ránu, ale při vstávání končetinu odlehčuje. Seznam zahrnuje změnu zatížení, nejen svalovou slabost. Ověřte omezení, bolest a pohyb, upravte úkol a zapište srovnatelný základ. Nepřecházejte rovnou na nestabilní polštář jen proto, že cílem je „posílení“.'),reading:{book:'canine-rehabilitation',page:197}},
 neurology:{lead:b('Neurological rehabilitation starts with localization and medical stability, then uses remaining function while preventing secondary complications. Recovery of walking is only one outcome.','Neurologická rehabilitace začíná lokalizací a zdravotní stabilitou, potom využívá zachovanou funkci a brání druhotným komplikacím. Obnova chůze je jen jeden výsledek.'),units:[
 u(b('1. Central and peripheral patterns','1. Centrální a periferní vzorce'),b('The CNS includes brain and spinal cord; peripheral nerves connect it to receptors and effectors. Brain disease may affect mentation, cranial nerve function and coordination. Spinal disease can affect limb movement, postural reactions and continence while leaving mentation normal. Peripheral injury tends to follow a nerve or neuromuscular distribution. Describe the pattern before proposing a disease name.','CNS tvoří mozek a mícha, periferní nervy jej spojují s receptory a efektory. Mozkové onemocnění může ovlivnit vědomí, hlavové nervy a koordinaci. Míšní může měnit pohyb, posturální reakce a kontinenci při normálním vědomí. Periferní poškození obvykle odpovídá nervu či nervosvalovému rozložení. Před názvem nemoci popište vzorec.'),b('Upper motor neuron pathways influence lower motor neurons, which directly innervate skeletal muscle. Their injury patterns differ in tone, reflexes and muscle change, but interpretation needs the full examination and timing. Paresis means reduced voluntary motor function; paralysis means absent voluntary motor function. Ataxia describes incoordination and can coexist with weakness. Avoid using these terms as synonyms.','Dráhy horního motoneuronu ovlivňují dolní motoneurony, které přímo inervují kosterní sval. Poškození se liší tonem, reflexy a svalovými změnami, výklad však potřebuje celé vyšetření a časový kontext. Paréza znamená sníženou volní motoriku, paralýza její nepřítomnost. Ataxie označuje nekoordinovanost a může doprovázet slabost. Pojmy nejsou synonyma.')),
 u(b('2. Disease course and clinical priorities','2. Průběh nemoci a klinické priority'),b('Disc extrusion, vascular spinal injury, degenerative disease and peripheral nerve trauma have different onset patterns, mechanisms and management. History of sudden onset, progression, pain and trauma helps direct diagnostic reasoning but cannot confirm a lesion alone. Imaging and veterinary neurological examination may be needed. Acute loss of walking or progressive deficits should not be treated as an opportunity to try more exercises first.','Extruze disku, cévní míšní poškození, degenerativní nemoc a trauma periferního nervu mají jiný vznik, mechanismus a postup. Náhlost, vývoj, bolest a úraz usměrňují rozvahu, samy však lézi nepotvrdí. Může být nutné zobrazování a veterinární neurologické vyšetření. Akutní ztráta chůze či progrese není příležitostí nejprve zkoušet další cviky.'),b('Medical and surgical restrictions remain important even when the main visible problem is neurological. Sensory impairment can conceal skin injury or excessive loading. A nonambulatory patient also needs assessment of bladder emptying, bowel care, positioning, pressure areas and access to resources. The plan should anticipate complications instead of waiting for them to become the main problem.','Zdravotní a chirurgická omezení platí i při převážně neurologickém problému. Porucha čití může skrýt kožní poranění či nadměrné zatížení. Nechodící pacient potřebuje také posoudit vyprazdňování měchýře, stolici, polohování, tlaková místa a přístup ke zdrojům. Plán má komplikacím předcházet, ne čekat na jejich převahu.')),
 u(b('3. Task practice and realistic interpretation','3. Nácvik úkolu a realistický výklad'),b('Choose practice according to residual voluntary control, sensation, strength and medical restrictions. Assistance should permit useful participation and protect the animal, not move it through an impressive-looking task regardless of control. Document what the patient initiates and what the handler supplies. A spinally generated stepping response is not equivalent to conscious sensation or fully recovered voluntary locomotion.','Nácvik volte podle zbylé volní kontroly, čití, síly a omezení. Pomoc má umožnit užitečnou účast a chránit zvíře, nikoli jej bez ohledu na řízení provést působivým úkolem. Zapište podíl pacienta a terapeuta. Míšně generovaná kroková reakce neznamená vědomé čití ani úplně obnovenou volní lokomoci.'),b('Neuroplasticity describes changes in nervous-system organization and function with experience or injury. It supports the rationale for meaningful practice, but it is not a promise of complete recovery. Reassessment should track neurological findings, everyday mobility, comfort, skin and continence. A useful compensation can improve life even if the damaged pathway does not return to normal.','Neuroplasticita popisuje změny uspořádání a funkce nervové soustavy při zkušenosti či poranění. Podporuje smysluplný nácvik, ale není slibem úplné obnovy. Kontrola sleduje neurologický nález, denní mobilitu, pohodlí, kůži a kontinenci. Užitečná kompenzace může zlepšit život i bez normalizace poškozené dráhy.'))
 ],rows:[r(b('Paresis','Paréza'),b('Reduced voluntary motor function','Snížená volní motorická funkce'),b('Record remaining initiation and assistance.','Zapište zachované zahájení a pomoc.')),r(b('Ataxia','Ataxie'),b('Incoordination','Nekoordinovanost'),b('Assess placement and pattern, not only force.','Hodnoťte umístění a vzorec, nejen sílu.')),r(b('Reflex withdrawal','Odtahový reflex'),b('A spinal response','Míšní odpověď'),b('Does not by itself prove conscious pain perception.','Sám neprokazuje vědomé vnímání bolesti.'))],example:b('Example: an assisted dog takes steps while its paws still drag and bedding remains wet. Do not label the patient recovered. Review voluntary contribution, skin protection and bladder function with the team. Mobility, tissue safety and nursing outcomes must all be considered in the next plan.','Příklad: podporovaný pes dělá kroky, ale vleče tlapky a lůžko zůstává mokré. Neoznačujte jej za uzdraveného. S týmem posuďte volní podíl, ochranu kůže a měchýř. Další plán musí zahrnout mobilitu, bezpečí tkání i ošetřování.'),reading:{book:'veterinary-technicians',page:172}},
 passive:{lead:b('Passive methods use externally applied movement or contact. To justify one, distinguish the target tissue, intended effect, measurement and limits; a technique name is not a treatment plan.','Pasivní metody využívají zevní pohyb či kontakt. Pro zdůvodnění odlište cílovou tkáň, účel, měření a limity; název techniky není léčebný plán.'),units:[
 u(b('1. PROM, stretching and joint mobilization','1. PROM, strečink a mobilizace kloubu'),b('Passive range of motion takes a joint through a permitted arc without requiring the patient to generate the movement. Stretching aims to influence the length or extensibility of a selected tissue. Joint mobilization addresses accessory movement such as glide or distraction. These tasks differ in direction, purpose and potential loading of a repair. They should not be grouped under the vague instruction “loosen the leg”.','Pasivní rozsah vede kloub povoleným obloukem bez nutnosti aktivního vytvoření pohybu pacientem. Strečink cílí na délku či poddajnost vybrané tkáně. Mobilizace řeší přídatný pohyb, například skluz a distrakci. Úkoly se liší směrem, účelem a zatížením opravy. Nelze je shrnout neurčitým „uvolnit nohu“.'),b('An apparent limit may arise from pain, muscle guarding, joint geometry, capsular restriction, swelling or a medical restriction. The correct response is not always to increase force. End-feel and stabilization require hands-on teaching and clinical interpretation. A reference range describes a population or method; it is not a target to force every patient to reach.','Zdánlivý limit může vznikat bolestí, obranným napětím, geometrií kloubu, pouzdrem, otokem či léčebným omezením. Správnou reakcí není vždy vyšší síla. Koncový pocit a stabilizace vyžadují praktickou výuku a klinický výklad. Referenční rozsah popisuje populaci či metodu, není cílem k vynucení u každého pacienta.')),
 u(b('2. Measuring movement reproducibly','2. Opakovatelné měření pohybu'),b('A goniometer uses a pivot and two arms aligned with defined segment landmarks. Record the joint, side, animal position and whether the measurement was active or passive. Adjacent joint motion can change the reading, especially with muscles spanning more than one joint. Consistent positioning matters as much as reading the scale correctly.','Goniometr používá osu a dvě ramena přiložená k určeným bodům segmentů. Zapište kloub, stranu, polohu zvířete a aktivní či pasivní měření. Sousední kloub může údaj změnit, zejména u vícekloubových svalů. Jednotná poloha je stejně důležitá jako správné odečtení stupnice.'),b('Interpret change alongside comfort and function. A small difference may reflect measurement variation rather than biological improvement. Record why a measurement stopped: discomfort, permitted range, loss of positioning or another limit. Reproducibility can be practised on a hinged model before any patient technique is attempted under supervision.','Změnu posuzujte s pohodlím a funkcí. Malý rozdíl může být variabilita měření místo biologického zlepšení. Zapište důvod zastavení: diskomfort, povolený rozsah, ztrátu polohy či jiný limit. Opakovatelnost nacvičte na kloubovém modelu před technikou na pacientovi pod dohledem.')),
 u(b('3. Massage and soft-tissue contact','3. Masáž a měkkotkáňový kontakt'),b('Passive touch establishes contact; effleurage uses gliding strokes; petrissage involves kneading or working soft tissues. A technique’s depth and pressure change its mechanical input and tolerance. Possible goals include comfort and selected soft-tissue problems, but evidence and suitability are intervention-specific. Massage does not replace active strengthening or correction of an unstable joint.','Pasivní kontakt vytváří dotyk, effleurage klouzavé tahy a petrissage hnětení či zpracování měkkých tkání. Hloubka a tlak mění mechanický vstup a toleranci. Cílem může být pohodlí či vybraný měkkotkáňový problém, ale důkazy a vhodnost jsou specifické. Masáž nenahrazuje aktivní posílení ani stabilizaci nestabilního kloubu.'),b('Before any manual method consider skin condition, wounds, unexplained swelling, pain, tissue repair and the animal’s willingness. Watch for avoidance and guarding throughout. A quiet animal can still be uncomfortable. Document the response and stop or reassess when the task is not tolerated; increasing pressure to overcome resistance is not a general therapeutic principle.','Před manuální metodou zvažte kůži, rány, neobjasněný otok, bolest, opravu tkáně a ochotu. Průběžně sledujte vyhýbání a obranné napětí. I tiché zvíře může být v nepohodě. Zapište reakci a při nesnášenlivosti přerušte či přehodnoťte; zvyšování tlaku k překonání odporu není obecný terapeutický princip.'))
 ],rows:[r(b('PROM','PROM'),b('Externally supplied joint arc','Zevně vedený kloubní oblouk'),b('Not an active strengthening stimulus.','Není aktivním posilovacím podnětem.')),r(b('Stretch','Strečink'),b('Targets tissue extensibility','Cílí na poddajnost tkáně'),b('Requires tissue-specific suitability.','Vyžaduje vhodnost pro danou tkáň.')),r(b('Mobilization','Mobilizace'),b('Accessory joint motion','Přídatný kloubní pohyb'),b('Requires anatomy, assessment and supervised technique.','Potřebuje anatomii, vyšetření a vedenou techniku.'))],example:b('Example: elbow extension measures less than last time. First check position, adjacent joints, pain and restrictions. If the dog is guarding, forcing the previous angle confuses measurement with treatment and may be inappropriate. Record the changed response and seek the reason before selecting an intervention.','Příklad: extenze lokte je menší než minule. Nejdříve ověřte polohu, sousední klouby, bolest a omezení. Při obranném napětí vynucování starého úhlu zaměňuje měření a terapii a může být nevhodné. Zapište změnu reakce a před volbou zásahu hledejte příčinu.'),reading:{book:'veterinary-technicians',page:72}}
};
Object.assign(theoryChapters,{
 active:{lead:b('Active therapy uses the patient’s own muscle activity to practise function. Task selection, dose, assistance and progression must all follow a defined goal and the patient’s response.','Aktivní terapie využívá vlastní svalovou aktivitu k nácviku funkce. Volba úkolu, dávka, pomoc a postup musí odpovídat cíli a reakci pacienta.'),units:[
 u(b('1. Match the task to the impairment','1. Přiřaďte úkol poruše'),b('Strength, endurance, balance and coordination overlap but are not identical. A task that challenges balance may offer little useful strengthening if the animal mainly avoids loading. Start with the functional problem, such as controlled rising or safe walking, then identify what limits it. Consider pain, joint stability, medical restrictions and ability to understand the task before choosing equipment.','Síla, vytrvalost, rovnováha a koordinace se překrývají, ale nejsou totožné. Balanční úkol nemusí účelně posilovat, pokud se zvíře hlavně vyhýbá zatížení. Začněte funkčním problémem, například řízeným vstáváním či bezpečnou chůzí, a určete omezení. Před pomůckou zvažte bolest, stabilitu, zdravotní limity a porozumění úkolu.'),b('A task can be active, active-assisted or largely supplied by a handler. Record the distinction. Assistance should enable an appropriate contribution without hiding loss of control. Motor learning benefits from meaningful, tolerable practice and feedback, while repeated poor-quality movement may reinforce compensation. Reward willingness without using a lure to overcome pain or fatigue.','Úkol může být aktivní, aktivně asistovaný nebo převážně vedený terapeutem. Rozdíl zapisujte. Pomoc má umožnit vhodný podíl bez zakrytí ztráty řízení. Motorickému učení prospívá smysluplný tolerovaný nácvik a zpětná vazba, opakovaný nekvalitní pohyb může upevňovat kompenzaci. Odměňujte ochotu bez přemáhání bolesti či únavy lákadlem.')),
 u(b('2. Dose and progression','2. Dávka a postup'),b('Dose includes frequency, intensity, time and task type. In animals, intensity may change through speed, incline, support, obstacle height, surface or leverage rather than a simple external weight. Record rest and the quality threshold that ends a set. A fixed repetition count without movement and recovery criteria is an incomplete prescription.','Dávka zahrnuje frekvenci, intenzitu, čas a druh úkolu. U zvířat intenzitu mění rychlost, sklon, podpora, výška překážky, povrch či páka, nejen vnější závaží. Zapište odpočinek a mez kvality ukončující sérii. Pevný počet bez kritérií pohybu a zotavení je neúplný předpis.'),b('Progress one meaningful variable after reassessment, while respecting tissue healing and medical restrictions. More complex is not always better. Monitor during the task and after it, including later stiffness, reduced willingness or worsened function. When tolerance deteriorates, return to the problem list: the answer may be a simpler task, less load or medical review rather than more motivation.','Po kontrole měňte jednu významnou proměnnou při respektování hojení a omezení. Složitější není vždy lepší. Sledujte stav během úkolu i později včetně ztuhlosti, menší ochoty či horší funkce. Při poklesu tolerance se vraťte k problémům: řešením může být jednodušší úkol, menší zátěž či kontrola, ne více motivace.')),
 u(b('3. Proprioceptive, balance and reflex-based tasks','3. Proprioceptivní, balanční a reflexní úkoly'),b('Proprioceptive information contributes to position awareness and movement control. Balance also depends on vision, vestibular input, strength and support conditions. Unstable surfaces simultaneously change several demands, so they are not a pure test of proprioception. Begin from an appropriate supported or stable task and use guarding to prevent falls; equipment should serve the goal rather than define it.','Propriocepce přispívá k informaci o poloze a řízení pohybu. Rovnováha závisí i na zraku, vestibulárním vstupu, síle a opoře. Nestabilní plocha mění několik nároků najednou, není čistým testem propriocepce. Vycházejte z vhodné podpory či stabilního úkolu a jistěte proti pádu; pomůcka slouží cíli, neurčuje jej.'),b('Spinal-reflex-induced training uses circuitry that can generate a response without a voluntary command. Its suitability depends on neurological assessment and the intended functional outcome. Eliciting movement is not proof of restored sensation or useful independent locomotion. Learn these techniques through supervised clinical teaching; painful stimulation and induced stumbling are not home learning exercises.','Trénink indukovaný míšními reflexy využívá okruhy vytvářející reakci bez volního povelu. Vhodnost závisí na neurologickém vyšetření a funkčním cíli. Vyvolaný pohyb neprokazuje čití ani účelnou samostatnou lokomoci. Techniky patří do klinické výuky; bolestivé podněty a vyvolané zakopávání nejsou domácí nácvik.'))
 ],rows:[r(b('Task difficulty','Obtížnost úkolu'),b('Complexity and support demands','Složitost a nároky na oporu'),b('Can increase without useful tissue loading.','Může růst bez účelného zatížení tkáně.')),r(b('Exercise dose','Dávka cvičení'),b('Frequency, intensity, time and type','Frekvence, intenzita, čas a druh'),b('Include rest and response monitoring.','Zahrňte odpočinek a sledování reakce.')),r(b('Progression','Postup'),b('A justified change after reassessment','Zdůvodněná změna po kontrole'),b('Not an automatic reward for completing repetitions.','Není automatickou odměnou za počet opakování.'))],example:b('Example: the dog remains on a balance cushion but braces, shifts away from one limb and needs increasing support. Duration alone suggests success, while quality suggests an unsuitable demand. Explain how you would simplify the task and reassess pain, control and assistance before progression.','Příklad: pes vydrží na balančním polštáři, ale zatíná se, odlehčuje jednu končetinu a potřebuje více opory. Délka naznačuje úspěch, kvalita nevhodnou náročnost. Vysvětlete zjednodušení a kontrolu bolesti, řízení a pomoci před dalším postupem.'),reading:{book:'veterinary-technicians',page:86}},
 modalities:{lead:b('Physical modalities deliver energy to tissue. Learn the energy type, intended biological effect, dose variables, evidence and precautions separately; no device name determines a safe patient-specific setting.','Fyzikální prostředky dodávají tkáni energii. Odděleně se učte druh energie, účinek, dávkovací proměnné, důkazy a opatření; název přístroje neurčuje bezpečné individuální nastavení.'),units:[
 u(b('1. Thermal and acoustic energy','1. Tepelná a akustická energie'),b('Heat and cold change tissue temperature through transfer processes such as conduction. The result depends on temperature difference, contact, barrier, duration, perfusion and tissue depth. Cold can reduce nerve-conduction speed and alter pain sensation; heat can alter circulation and tissue extensibility. These effects do not make either suitable for every painful area. Impaired sensation or circulation increases concern for unnoticed tissue injury.','Teplo a chlad mění teplotu přenosem, například vedením. Výsledek závisí na teplotním rozdílu, kontaktu, bariéře, délce, prokrvení a hloubce. Chlad může zpomalit nervové vedení a změnit bolest, teplo ovlivnit cirkulaci a poddajnost. Tím nejsou vhodné pro každé bolestivé místo. Porucha čití či cirkulace zvyšuje obavu z nepozorovaného poškození.'),b('Therapeutic ultrasound delivers acoustic energy rather than an electrical stimulus. Frequency affects penetration and absorption; intensity, duty cycle, area and coupling affect delivery. Air at the interface transmits ultrasound poorly, so coupling and coat preparation matter. Thermal and nonthermal effects depend on the application. Diagnostic imaging ultrasound has a different purpose and should not be confused with a treatment protocol.','Terapeutický ultrazvuk dodává akustickou energii, nikoli elektrický podnět. Frekvence ovlivňuje průnik a absorpci, intenzita, pracovní cyklus, plocha a kontakt dodávku. Vzduch na rozhraní přenáší ultrazvuk špatně, proto záleží na vazebním prostředí a srsti. Tepelné a netepelné účinky závisejí na aplikaci. Diagnostické zobrazování má jiný účel a není terapeutickým protokolem.')),
 u(b('2. Electrical, magnetic and light-based methods','2. Elektrické, magnetické a světelné metody'),b('TENS is used primarily for pain modulation; NMES aims to activate muscle through electrical stimulation. Waveform, pulse duration, frequency, amplitude, electrode configuration and tissue impedance affect the response. Sensory perception and visible contraction are different endpoints. Muscle activation does not automatically produce a useful functional task, and denervation changes the clinical problem. Settings require assessment and device-specific instruction.','TENS se používá především k modulaci bolesti, NMES k elektrické aktivaci svalu. Odpověď mění průběh proudu, délka pulzu, frekvence, amplituda, elektrody a impedance tkáně. Čití a viditelná kontrakce jsou jiné cíle. Aktivace svalu automaticky netvoří funkční úkol a denervace mění klinický problém. Nastavení potřebuje vyšetření a pokyny pro přístroj.'),b('Pulsed electromagnetic fields and magnetic stimulation should not be treated as synonyms for all electrical methods; field characteristics and therapeutic aims differ. Photobiomodulation uses light, with effects depending on wavelength, delivered energy, area and tissue. Power multiplied by exposure time gives energy, but energy alone does not establish the tissue dose or benefit. Device-appropriate eye protection is essential for laser use.','Pulzní elektromagnetická pole a magnetická stimulace nejsou synonymem všech elektrických metod; liší se pole i cíle. Fotobiomodulace využívá světlo a závisí na vlnové délce, energii, ploše a tkáni. Výkon krát doba dává energii, energie sama však neurčuje dávku v tkáni ani přínos. U laseru je zásadní ochrana očí odpovídající přístroji.')),
 u(b('3. Shockwave, precautions and evidence','3. Rázová vlna, opatření a důkazy'),b('Shockwave systems produce mechanical pressure waves. Focused and radial systems differ in delivery and are not interchangeable merely because both are called shockwave. Target localization, patient selection and analgesia or sedation considerations require veterinary planning. Relief of pain after an intervention does not establish that the tissue can tolerate unrestricted exercise.','Systémy rázové vlny vytvářejí mechanické tlakové vlny. Fokusované a radiální se liší dodávkou a nejsou zaměnitelné jen podle názvu. Lokalizace, výběr pacienta a úvaha o analgezii či sedaci vyžadují veterinární plán. Úleva po zásahu neprokazuje toleranci neomezeného cvičení.'),b('For any device, distinguish a contraindication from a precaution requiring adaptation or specialist advice. Check tissue condition, sensation, implants, relevant disease and manufacturer instructions. Ask whether evidence concerns the same species, condition, device and outcome. Proposed cellular mechanisms are not equivalent to demonstrated clinical benefit. At the exam explain a defensible choice and monitoring plan rather than reciting a universal numerical recipe.','U přístroje odlište kontraindikaci od opatření vyžadujícího úpravu či konzultaci. Kontrolujte tkáň, čití, implantáty, nemoci a pokyny výrobce. Zjišťujte, zda důkazy odpovídají druhu, diagnóze, přístroji a výsledku. Navržený buněčný mechanismus není prokázaný klinický přínos. U zkoušky zdůvodněte volbu a sledování místo univerzálního číselného receptu.'))
 ],rows:[r(b('Heat / cold','Teplo / chlad'),b('Thermal transfer','Tepelný přenos'),b('Monitor skin, sensation and circulation.','Sledujte kůži, čití a cirkulaci.')),r(b('Ultrasound','Ultrazvuk'),b('Acoustic energy','Akustická energie'),b('Coupling and target depth affect delivery.','Kontakt a hloubka mění dodávku.')),r(b('TENS / NMES','TENS / NMES'),b('Electrical stimulation','Elektrická stimulace'),b('Distinguish pain modulation from muscle activation.','Odlište modulaci bolesti a aktivaci svalu.')),r(b('PEMF / magnetic stimulation','PEMF / magnetická stimulace'),b('Changing magnetic fields','Proměnná magnetická pole'),b('Verify the exact device and terminology.','Ověřte konkrétní přístroj a terminologii.')),r(b('Laser','Laser'),b('Light energy','Světelná energie'),b('Eye protection and dose variables matter.','Důležitá ochrana očí a dávkovací proměnné.')),r(b('Shockwave','Rázová vlna'),b('Mechanical pressure waves','Mechanické tlakové vlny'),b('Requires target-specific veterinary planning.','Vyžaduje cílený veterinární plán.'))],example:b('Example: an examiner presents an NMES unit. Identify it as electrical stimulation intended to elicit muscle activation, then discuss nerve/muscle status, skin, electrodes, response and a functional goal. Explain why you cannot select settings from the device photograph alone. Keep FMS terminology distinct and confirm the course’s exact device meaning.','Příklad: zkoušející ukáže NMES. Určete elektrickou stimulaci pro aktivaci svalu, potom stav nervu a svalu, kůži, elektrody, reakci a funkční cíl. Vysvětlete, proč z fotografie nelze zvolit nastavení. Pojem FMS rozlišujte a ověřte jeho konkrétní význam ve výuce.'),reading:{book:'canine-rehabilitation',page:354}},
 hydrotherapy:{lead:b('Water changes support, resistance and the physiological demands of movement. Hydrotherapy is a controlled clinical environment, not simply exercise made easier by buoyancy.','Voda mění oporu, odpor a fyziologické nároky pohybu. Hydroterapie je řízené klinické prostředí, nikoli jen cvičení usnadněné vztlakem.'),units:[
 u(b('1. Physical properties and their interaction','1. Fyzikální vlastnosti a jejich souhra'),b('Buoyancy is an upward force related to displaced water. Greater immersion generally changes effective loading, but the exact distribution also depends on body shape, posture and movement. Hydrostatic pressure increases with depth and acts on immersed surfaces. Viscosity and drag resist motion; changing speed and exposed surface changes that resistance. These properties act together, so reducing weight bearing does not necessarily reduce total effort.','Vztlak je síla vzhůru související s vytlačenou vodou. Větší ponoření obecně mění účinné zatížení, přesné rozložení závisí také na tvaru, postoji a pohybu. Hydrostatický tlak roste s hloubkou a působí na ponořené plochy. Viskozita a odpor brání pohybu; mění je rychlost a exponovaná plocha. Účinky se kombinují, menší opora proto nemusí znamenat menší celkovou námahu.'),b('Water temperature affects comfort and heat exchange; immersion and exertion can alter cardiovascular and respiratory demand. Refraction also changes how the therapist sees limbs through water. Interpret apparent movement with that limitation in mind. Water level is a clinical variable, not a universal setting based only on the dog’s height.','Teplota vody mění pohodlí a výměnu tepla, ponoření a námaha mohou měnit oběhové a dechové nároky. Lom světla mění i pohled terapeuta na končetiny ve vodě. Zdánlivý pohyb vykládejte s tímto omezením. Hladina je klinická proměnná, nikoli univerzální nastavení jen podle výšky psa.')),
 u(b('2. Swimming and underwater walking','2. Plavání a podvodní chůze'),b('In swimming, paws do not have the same repeated ground support as treadmill walking and limb excursions differ. Underwater treadmill work can combine buoyancy with a controlled support surface and speed, but it still requires suitable coordination and monitoring. The goals and contraindications differ between patients. A dog that swims enthusiastically is not automatically performing the movement pattern required for its rehabilitation goal.','Při plavání tlapky nemají stejnou opakovanou oporu jako na pásu a liší se rozsahy končetin. Podvodní pás kombinuje vztlak s řízenou podložkou a rychlostí, stále však potřebuje vhodnou koordinaci a sledování. Cíle a kontraindikace se mezi pacienty liší. Nadšeně plavající pes automaticky neprovádí vzorec potřebný pro svůj cíl.'),b('Selection considers medical stability, wounds and infection control, continence, cardiopulmonary tolerance, pain, fear and safe access. A patient may be unsuitable now but appropriate later after a problem is resolved. Water-based activity must respect the same repair restrictions as land-based rehabilitation; buoyancy does not cancel them.','Výběr zohledňuje stabilitu, rány a infekce, kontinenci, oběhovou a dechovou toleranci, bolest, strach a přístup. Pacient může být nyní nevhodný a později vhodný po vyřešení problému. Vodní aktivita respektuje stejná omezení opravy jako rehabilitace na souši; vztlak je neruší.')),
 u(b('3. Handling and session reasoning','3. Manipulace a rozvaha o jednotce'),b('Before treatment plan entry, exit, acclimatization, support, emergency removal and equipment hygiene. Non-slip access and appropriate assistance matter before the animal reaches the water. Familiarization should allow voluntary participation; forcing a frightened dog into a tank can compromise welfare and the quality of movement. A flotation aid does not eliminate the need for continuous supervision.','Před terapií naplánujte vstup, výstup, zvykání, podporu, nouzové vyjmutí a hygienu. Neklouzavý přístup a pomoc jsou důležité již před vodou. Zvykání má umožnit dobrovolnost; nucení vystrašeného psa do nádrže může poškodit welfare i kvalitu pohybu. Plovací pomůcka neruší potřebu trvalého dohledu.'),b('Monitor breathing effort, posture, coordination, willingness and fatigue. Record water level, speed, assistance and observed quality so later sessions are comparable. A session may need to end before a planned duration. Explain the intended effect of each variable and the response that would make you stop, rather than equating more time in water with a better treatment.','Sledujte dechové úsilí, postoj, koordinaci, ochotu a únavu. Zapište hladinu, rychlost, pomoc a kvalitu pro srovnání. Jednotka může skončit před plánovaným časem. Vysvětlete zamýšlený účinek proměnných a reakci k ukončení místo ztotožnění delšího pobytu s lepší terapií.'))
 ],rows:[r(b('Buoyancy','Vztlak'),b('Changes effective support','Mění účinnou oporu'),b('Does not remove all joint or muscle demand.','Neodstraňuje všechny nároky kloubů a svalů.')),r(b('Drag','Odpor vody'),b('Resists movement','Brání pohybu'),b('Can increase effort as speed changes.','Při změně rychlosti může zvýšit námahu.')),r(b('Water depth','Hloubka vody'),b('Changes several forces simultaneously','Mění několik sil současně'),b('Select for the patient and task.','Volte podle pacienta a úkolu.'))],example:b('Example: increasing the water level reduces visible weight bearing, but the dog pants more and loses coordination. The session is not necessarily easier. Reassess respiratory demand, fatigue, fear and support; do not continue simply because buoyancy was intended to protect a joint.','Příklad: vyšší hladina sníží viditelnou oporu, ale pes více funí a ztrácí koordinaci. Jednotka nemusí být lehčí. Posuďte dechové nároky, únavu, strach a podporu; nepokračujte jen proto, že vztlak měl chránit kloub.'),reading:{book:'canine-rehabilitation',page:537}},
 support:{lead:b('Supportive care makes rehabilitation feasible and prevents avoidable complications. Skin, elimination, nutrition, aids and quality of life are clinical outcomes alongside movement.','Podpůrná péče umožňuje rehabilitaci a brání zbytečným komplikacím. Kůže, vylučování, výživa, pomůcky a kvalita života jsou klinické výsledky vedle pohybu.'),units:[
 u(b('1. Nursing the dependent patient','1. Ošetřování závislého pacienta'),b('An immobile animal may need help with positioning, access to food and water, hygiene and movement between resting areas. Pressure, moisture, friction and reduced sensation can contribute to skin damage. Bedding, inspection and an individualized repositioning plan belong to the treating team’s care plan. A patient that appears quiet may still be uncomfortable or unable to shift away from pressure.','Imobilní zvíře může potřebovat pomoc s polohou, vodou a krmivem, hygienou a přesunem. Tlak, vlhkost, tření a horší čití přispívají ke kožnímu poškození. Lůžko, prohlídky a individuální polohování patří do plánu týmu. Tichý pacient může být v nepohodě nebo neschopen uniknout tlaku.'),b('Record voluntary elimination, leakage, straining, urine changes and skin soiling. Wet bedding may reflect overflow rather than adequate bladder emptying. Bladder management depends on veterinary assessment of the urinary and neurological problem. Prescribed techniques require direct training and review; trying expression on a healthy dog is not a safe way to learn the examination.','Zapisujte volní vylučování, únik, tlačení, změny moči a znečištění. Mokré lůžko může znamenat přetékání místo dostatečného vyprázdnění. Péče o měchýř závisí na veterinárním urologickém a neurologickém posouzení. Předepsané techniky potřebují přímou výuku a kontrolu; exprese zdravého psa není bezpečný nácvik vyšetření.')),
 u(b('2. Aids, orthoses, prostheses and bandages','2. Pomůcky, ortézy, protézy a bandáže'),b('A sling or support harness assists a task, an orthosis supports or modifies an existing segment, and a prosthesis replaces a missing segment. A cart can improve mobility for selected patients but introduces fit, skin and environmental demands. Every aid needs a defined purpose and assessment of pressure points, breathing, toileting clearance and the owner’s ability to use it.','Závěs či podpůrný postroj pomáhá úkolu, ortéza podpírá nebo ovlivňuje přítomný segment a protéza nahrazuje chybějící. Vozík může zlepšit mobilitu vybraných pacientů, ale přináší nároky na velikost, kůži a prostředí. Pomůcka potřebuje účel a kontrolu tlaků, dechu, prostoru pro vylučování i schopnosti majitele.'),b('Bandages may protect or support, but an inappropriate application can impair circulation, trap moisture or damage skin. Fit is not a one-time event: swelling, growth, body condition and activity can change it. New rubbing, swelling, odor or discomfort requires review. Teaching should include checking and removal/contact instructions supplied by the prescribing team, not only how an aid looks when fitted.','Bandáž chrání či podporuje, nevhodná aplikace ale může omezit cirkulaci, zadržet vlhkost či poškodit kůži. Velikost není jednorázová věc: mění ji otok, růst, kondice i aktivita. Nové oděrky, otok, zápach či nepohoda vyžadují kontrolu. Výuka zahrnuje kontroly a pokyny týmu k odstranění či kontaktu, nejen vzhled nasazené pomůcky.')),
 u(b('3. Nutrition and palliative goals','3. Výživa a paliativní cíle'),b('Body weight, body condition score and muscle condition score answer different questions. An overweight animal can also have muscle loss. Review total intake, treats, supplements and disease-related dietary needs with the veterinary team. Energy reduction, when indicated, must be planned without assuming that less food automatically preserves adequate nutrients or muscle. Supplements vary in composition and evidence.','Hmotnost, skóre tělesné a svalové kondice odpovídají na různé otázky. Obézní zvíře může ztrácet svaly. S týmem posuďte celý příjem, pamlsky, doplňky a dietní potřeby nemocí. Potřebné omezení energie plánujte bez předpokladu, že méně krmiva zachová dost živin a svaly. Doplňky se liší složením a důkazy.'),b('Palliative rehabilitation prioritizes comfort, valued activities and manageable care rather than restoring every impairment. Discuss goals with the owner and veterinary team and track trends in quality of life. A technically possible treatment can still impose more burden than benefit. Good communication includes how to recognize deterioration and when to revisit the plan.','Paliativní rehabilitace upřednostňuje pohodlí, důležité činnosti a zvládnutelnou péči před obnovou každé poruchy. Cíle domluvte s majitelem a týmem a sledujte kvalitu života. Technicky možná léčba může přinášet více zátěže než užitku. Komunikace zahrnuje rozpoznání zhoršení a změnu plánu.'))
 ],rows:[r(b('Body weight','Hmotnost'),b('Total mass','Celková hmotnost'),b('Cannot distinguish fat from muscle.','Nerozliší tuk a svaly.')),r(b('Body condition','Tělesná kondice'),b('Assessment of fat reserves','Posouzení tukových zásob'),b('Interpret with species-appropriate scoring.','Vykládejte pomocí škály pro daný druh.')),r(b('Muscle condition','Svalová kondice'),b('Assessment of muscle loss','Posouzení úbytku svalů'),b('Can worsen despite excess body fat.','Může se zhoršit i při nadbytku tuku.'))],example:b('Example: a harness allows longer walking but causes a red pressure area. The mobility gain does not justify the skin injury. Stop its use pending fit and skin review, consider a safe alternative and update owner checks. Success must include skin integrity and comfort.','Příklad: postroj umožní delší chůzi, ale vytvoří červený otlak. Zisk mobility neospravedlňuje poškození. Použití přerušte do kontroly kůže a velikosti, zvažte bezpečnou alternativu a upravte kontroly majitele. Úspěch zahrnuje neporušenou kůži i komfort.'),reading:{book:'veterinary-technicians',page:162}},
 cases:{lead:b('A case answer should show a chain of reasoning from evidence to action. Make uncertainty visible, link every intervention to a goal and explain how reassessment changes the plan.','Odpověď na případ má ukázat řetězec rozvahy od podkladu ke kroku. Uveďte nejistotu, propojte zásah s cílem a vysvětlete změnu plánu při kontrole.'),units:[
 u(b('1. Read the report critically','1. Kriticky přečtěte zprávu'),b('Extract identity, species, age, diagnosis, side, procedure and date, medication, comorbidities and explicit restrictions. Separate a confirmed diagnosis from a suspected one. Identify what the report does not say, such as whether a repair has been cleared for increased loading. If the owner’s account, report and current examination disagree, clarification comes before a confident prescription.','Vyberte identitu, druh, věk, diagnózu, stranu, výkon a datum, léky, další nemoci a omezení. Oddělte potvrzenou diagnózu od podezření. Určete, co zpráva neříká, například povolení vyšší zátěže opravy. Při rozporu majitele, zprávy a dnešního nálezu předchází objasnění sebejistému předpisu.'),b('Build a prioritized problem list from findings: pain, altered support, limited permitted motion, skin risk or environmental barriers. Avoid turning every observation into a diagnosis. State the evidence behind each interpretation and the consequence for treatment. The strongest case answer can say “I need this information before proceeding” and explain exactly why.','Z nálezů vytvořte prioritní problémy: bolest, změněnou oporu, malý povolený pohyb, riziko kůže či bariéry doma. Nepřevádějte každé pozorování na diagnózu. U výkladu uveďte důkaz a důsledek pro terapii. Dobrá odpověď může říct „před pokračováním potřebuji tento údaj“ a přesně vysvětlit proč.')),
 u(b('2. Turn problems into a protocol','2. Převeďte problémy na protokol'),b('Use a baseline and a measurable functional goal under defined conditions. Then select an intervention, its permitted dose or boundaries, responsible person, monitoring and review point. A goal might concern a safer daily transfer or a reproducible improvement in a permitted walking task. The exact target must suit the patient rather than an arbitrary textbook number.','Použijte základ a měřitelný funkční cíl v určených podmínkách. Potom zvolte zásah, povolenou dávku či hranice, odpovědnou osobu, sledování a kontrolu. Cíl může být bezpečnější denní přesun či opakovatelné zlepšení povolené chůze. Přesný cíl odpovídá pacientovi, ne libovolnému tabulkovému číslu.'),b('Include progression, regression and referral decisions. State which findings permit a change and which require stopping or medical review. Explain why an attractive intervention is withheld when its risk or demand is inappropriate. A protocol is a decision framework that responds to the patient, not a fixed list of appointments.','Zahrňte postup, ústup i odeslání. Uveďte nálezy povolující změnu a vyžadující přerušení či lékařskou kontrolu. Vysvětlete vynechání lákavé metody při nevhodném riziku či nároku. Protokol je rozhodovací rámec reagující na pacienta, ne pevný seznam návštěv.')),
 u(b('3. Documentation and owner education','3. Dokumentace a edukace majitele'),b('A SOAP-style record separates subjective information, objective findings, assessment and plan. This makes it easier for another clinician to understand what happened. Include adverse responses and incomplete tasks as well as gains. Use consistent terms and units; a phrase like “much better” is difficult to reassess without a task or measure attached.','Záznam typu SOAP odděluje subjektivní údaje, objektivní nálezy, hodnocení a plán. Další odborník tak snáze pochopí průběh. Zahrňte nežádoucí reakce a nedokončené úkoly i zlepšení. Používejte jednotné pojmy a jednotky; „mnohem lepší“ se bez úkolu či měřítka těžko kontroluje.'),b('Demonstrate only the agreed home task, then ask the owner to explain and show it back. Check setup, permitted movement, stop signs and contact information. Simplify the plan to what the household can reliably do. Written instructions reinforce the discussion but do not replace checking understanding. Cats may need different motivation and environmental arrangements from dogs.','Předveďte jen dohodnutý domácí úkol a nechte majitele vysvětlit a ukázat jej zpět. Ověřte přípravu, povolený pohyb, stop příznaky a kontakt. Plán zjednodušte na spolehlivě proveditelné kroky. Písemné pokyny podporují rozhovor, nenahrazují kontrolu porozumění. Kočka může potřebovat jinou motivaci a prostředí než pes.'))
 ],rows:[r(b('Problem','Problém'),b('A supported limitation','Podložené omezení'),b('Example: difficulty with a daily transfer.','Příklad: obtížný běžný přesun.')),r(b('Goal','Cíl'),b('A measurable meaningful change','Měřitelná smysluplná změna'),b('Define conditions, baseline and review.','Určete podmínky, základ a kontrolu.')),r(b('Intervention','Zásah'),b('A justified means to the goal','Zdůvodněný prostředek k cíli'),b('Specify restrictions and response monitoring.','Uveďte omezení a sledování reakce.'))],example:b('Example: an owner reports “the dog is better” but cannot demonstrate the home task as prescribed. Record the reported benefit, observe the misunderstanding and reteach with a simpler instruction. The next plan should address adherence and safety, rather than increasing exercise based only on the positive report.','Příklad: majitel říká „pes je lepší“, ale neumí předvést předepsaný úkol. Zapište hlášený přínos, pozorujte neporozumění a naučte jednodušší pokyn. Další plán řeší provedení a bezpečí, ne zvýšení cvičení jen podle pozitivního hlášení.'),reading:{book:'veterinary-technicians',page:64}},
 special:{lead:b('Special cases require adaptation of goals, monitoring and acceptable treatment burden. Obesity, aging, critical illness and cardiac disease are different contexts, often present together.','Zvláštní případy vyžadují přizpůsobení cílů, sledování a přijatelné zátěže péče. Obezita, stáří, kritický stav a srdeční nemoc jsou různé kontexty, často současné.'),units:[
 u(b('1. Obesity and osteoarthritis','1. Obezita a osteoartróza'),b('Excess body mass increases the demand of many tasks, while OA-related pain can reduce activity and muscle capacity. This can create a self-reinforcing limitation. Assess weight, fat reserves and muscle condition separately. Weight management should coordinate nutrition and suitable activity with pain care; simply forcing longer walks may worsen tolerance. The goal is better function and comfort while preserving muscle.','Nadbytečná hmotnost zvyšuje nároky mnoha úkolů, bolest při OA snižuje aktivitu a svalovou kapacitu. Omezení se může vzájemně posilovat. Odděleně hodnoťte hmotnost, tuk a svaly. Řízení hmotnosti propojuje výživu a vhodnou aktivitu s léčbou bolesti; nucené delší procházky mohou zhoršit toleranci. Cílem je funkce a pohodlí při ochraně svalů.'),b('Environmental changes can reduce unnecessary strain: secure footing, accessible resources and an appropriate resting area. For cats, reduced jumping, grooming or litter-box access may reveal problems that are not described as lameness. Ask about valued daily activities and choose outcomes the owner can actually observe consistently.','Úpravy prostředí mohou omezit zbytečnou námahu: jistý povrch, dostupné zdroje a vhodný odpočinek. U koček menší skákání, péče o srst či přístup na toaletu odhalí potíže nepopisované jako kulhání. Ptejte se na důležité denní aktivity a vybírejte výsledky, které majitel dokáže jednotně sledovat.')),
 u(b('2. Geriatric patients','2. Geriatričtí pacienti'),b('Age is a context, not a diagnosis. Pain, sarcopenia, sensory impairment, cognitive change and organ disease may each affect function. Frailty concerns reduced reserve and vulnerability, not merely chronological age. A senior that declines suddenly needs assessment for a new problem rather than an assumption that decline is inevitable.','Věk je kontext, ne diagnóza. Funkci mění bolest, sarkopenie, porucha smyslů, kognice i orgánové nemoci. Křehkost znamená menší rezervu a zranitelnost, ne pouhý kalendářní věk. Náhlé zhoršení seniora potřebuje posouzení nového problému místo předpokladu nevyhnutelného stáří.'),b('Choose manageable tasks, a predictable environment and sufficient recovery. Track comfort, participation and useful activities rather than athletic performance alone. Several conditions and medications can change together, so reassessment and team communication matter. When recovery is limited, palliative goals may remain highly valuable: easier access to resources and comfortable social participation can be meaningful outcomes.','Volte zvládnutelné úkoly, předvídatelné prostředí a zotavení. Sledujte pohodlí, účast a užitečné činnosti, nejen sportovní výkon. Současně se mění více nemocí a léků, proto jsou důležité kontroly a komunikace. Při omezené obnově zůstávají cenné paliativní cíle: dostupnost zdrojů a pohodlný sociální kontakt.')),
 u(b('3. Critical and cardiac patients','3. Kriticky nemocní a kardiologičtí pacienti'),b('Critical illness places stabilization and organ support ahead of exercise. Selected positioning and movement must fit the treating team’s monitoring, lines, wounds and restrictions. Tolerance can change quickly. The rehabilitation contribution may initially be protection from secondary complications rather than performance training. Never transfer a routine orthopedic schedule to an unstable patient.','Kritický stav staví stabilizaci a podporu orgánů před cvičení. Vybrané polohování a pohyb musí odpovídat monitoraci, vstupům, ranám a omezením týmu. Tolerance se rychle mění. Rehabilitace může nejprve chránit před komplikacemi místo tréninku výkonu. Běžný ortopedický rozvrh nepřenášejte na nestabilního pacienta.'),b('Cardiac conditions differ in severity and hemodynamic effects. Obtain individualized activity guidance and monitoring rather than prescribing a universal target heart rate. Watch the animal’s breathing effort, willingness and recovery within that plan. New respiratory distress, collapse or marked intolerance requires stopping and veterinary assessment. Hydrotherapy also changes physiological demand and needs individual review, even when buoyancy reduces limb loading.','Srdeční nemoci se liší závažností a hemodynamikou. Vyžádejte individuální aktivitu a sledování místo univerzální cílové frekvence. V rámci plánu sledujte dechové úsilí, ochotu a zotavení. Nová dechová tíseň, kolaps či výrazná intolerance vyžadují ukončení a veterinární posouzení. I hydroterapie mění fyziologické nároky a potřebuje kontrolu, přestože vztlak snižuje zatížení končetin.'))
 ],rows:[r(b('Obesity / OA','Obezita / OA'),b('Load, pain and muscle interact','Zátěž, bolest a svaly se ovlivňují'),b('Coordinate nutrition, pain care and activity.','Propojte výživu, bolest a aktivitu.')),r(b('Geriatric change','Geriatrické změny'),b('Several impairments may coexist','Může souběžně existovat více poruch'),b('Do not attribute every new sign to age.','Nepřipisujte každý nový příznak věku.')),r(b('Critical / cardiac disease','Kritický stav / srdeční nemoc'),b('Physiological reserve may limit tasks','Úkoly může omezit fyziologická rezerva'),b('Medical stability and tailored monitoring come first.','Přednost má stabilita a individuální sledování.'))],example:b('Example: an older overweight dog with heart disease becomes less willing to walk. It is unsafe to assume deconditioning alone. Review pain, cardiopulmonary status, medication and home function with the team. Goals may initially focus on comfort and safe daily activity rather than increasing distance.','Příklad: starší obézní pes se srdeční nemocí méně ochotně chodí. Nelze předpokládat pouze pokles kondice. S týmem zkontrolujte bolest, oběhový a dechový stav, léky a funkci doma. Cíle mohou nejprve řešit pohodlí a bezpečný denní pohyb místo vzdálenosti.'),reading:{book:'canine-rehabilitation',page:639}}
} satisfies Record<string,TheoryChapter>);
